mod video;

use std::time::{Duration, Instant};

use anyhow::{Result, anyhow};
use gpui::{
    AnyElement, App, Application, Bounds, Context, FocusHandle, KeyDownEvent, MouseButton, MouseDownEvent,
    MouseMoveEvent, SharedString, TitlebarOptions, Window, WindowBounds, WindowOptions, div,
    prelude::*, px, rgb, rgba, size,
};
use raw_window_handle::{HasWindowHandle, RawWindowHandle};
use video::VideoSurface;
use windows::Win32::Foundation::HWND;

/// Generated by mpv, so the app runs with no media file.
const TEST_PATTERN: &str = "av://lavfi:testsrc2=size=1920x1080:rate=30:duration=120";
const CONTROLS_TIMEOUT: Duration = Duration::from_millis(2500);
/// Horizontal distance from the window edge to the seek bar.
const SEEK_INSET: f32 = 40.0;

fn native_hwnd(window: &Window) -> Result<HWND> {
    let handle = HasWindowHandle::window_handle(window).map_err(|e| anyhow!("{e}"))?;
    match handle.as_raw() {
        RawWindowHandle::Win32(h) => Ok(HWND(h.hwnd.get() as *mut _)),
        other => Err(anyhow!("unsupported window handle: {other:?}")),
    }
}

fn format_time(seconds: f64) -> String {
    let total = seconds.max(0.0) as u64;
    let (h, m, s) = (total / 3600, total / 60 % 60, total % 60);
    if h > 0 {
        format!("{h}:{m:02}:{s:02}")
    } else {
        format!("{m}:{s:02}")
    }
}

struct Player {
    video: VideoSurface,
    focus: FocusHandle,
    position: f64,
    duration: f64,
    paused: bool,
    last_activity: Instant,
    pipeline: String,
}

impl Player {
    fn new(source: &str, window: &mut Window, cx: &mut Context<Self>) -> Result<Self> {
        let video = VideoSurface::new(native_hwnd(window)?, source)?;
        let focus = cx.focus_handle();
        focus.focus(window);

        cx.observe_window_bounds(window, |this, _, _| this.video.sync_size())
            .detach();
        cx.spawn(async move |this, cx| {
            loop {
                cx.background_executor()
                    .timer(Duration::from_millis(100))
                    .await;
                if this.update(cx, |this, cx| this.tick(cx)).is_err() {
                    break;
                }
            }
        })
        .detach();

        Ok(Self {
            video,
            focus,
            position: 0.0,
            duration: 0.0,
            paused: false,
            last_activity: Instant::now(),
            pipeline: String::new(),
        })
    }

    fn tick(&mut self, cx: &mut Context<Self>) {
        self.position = self.video.position();
        self.duration = self.video.duration();
        self.paused = self.video.paused();
        let pipeline = self.video.pipeline();
        if pipeline != self.pipeline {
            eprintln!("[video] {pipeline}");
            self.pipeline = pipeline;
        }
        cx.notify();
    }

    fn poke(&mut self, cx: &mut Context<Self>) {
        self.last_activity = Instant::now();
        cx.notify();
    }

    fn controls_visible(&self) -> bool {
        self.paused || self.last_activity.elapsed() < CONTROLS_TIMEOUT
    }

    fn on_key(&mut self, event: &KeyDownEvent, window: &mut Window, cx: &mut Context<Self>) {
        match event.keystroke.key.as_str() {
            "space" => self.video.toggle_pause(),
            "left" => self.video.seek_by(-10.0),
            "right" => self.video.seek_by(10.0),
            "f" => window.toggle_fullscreen(),
            "escape" if window.is_fullscreen() => window.toggle_fullscreen(),
            _ => return,
        }
        self.poke(cx);
    }

    fn on_seek(&mut self, event: &MouseDownEvent, window: &mut Window, cx: &mut Context<Self>) {
        let width = f32::from(window.viewport_size().width) - SEEK_INSET * 2.0;
        let x = f32::from(event.position.x) - SEEK_INSET;
        if width > 0.0 && self.duration > 0.0 {
            let fraction = (x / width).clamp(0.0, 1.0) as f64;
            self.video.seek_to(fraction * self.duration);
        }
        self.poke(cx);
    }

    fn button(
        &self,
        id: &'static str,
        label: impl Into<SharedString>,
        cx: &mut Context<Self>,
        action: impl Fn(&mut Self, &mut Window) + 'static,
    ) -> AnyElement {
        div()
            .id(id)
            .px_3()
            .py_1()
            .rounded_md()
            .bg(rgba(0xffffff22))
            .hover(|s| s.bg(rgba(0xffffff44)))
            .cursor_pointer()
            .child(label.into())
            .on_mouse_down(
                MouseButton::Left,
                cx.listener(move |this, _: &MouseDownEvent, window, cx| {
                    cx.stop_propagation();
                    action(this, window);
                    this.poke(cx);
                }),
            )
            .into_any_element()
    }

    fn controls(&self, cx: &mut Context<Self>) -> AnyElement {
        let progress = if self.duration > 0.0 {
            (self.position / self.duration).clamp(0.0, 1.0) as f32
        } else {
            0.0
        };
        let play_label = if self.paused { "Play" } else { "Pause" };
        let time = format!(
            "{} / {}",
            format_time(self.position),
            format_time(self.duration)
        );

        div()
            .absolute()
            .bottom_6()
            .left_6()
            .right_6()
            .p_4()
            .flex()
            .flex_col()
            .gap_3()
            .rounded_xl()
            .bg(rgba(0x101218c8))
            .text_color(rgb(0xf4f5f7))
            .text_sm()
            // The bar is opaque to clicks so it doesn't toggle pause underneath.
            .on_mouse_down(MouseButton::Left, |_, _, cx| cx.stop_propagation())
            .child(
                div()
                    .id("seek")
                    .h_2()
                    .w_full()
                    .rounded_full()
                    .bg(rgba(0xffffff33))
                    .cursor_pointer()
                    .on_mouse_down(MouseButton::Left, cx.listener(Self::on_seek))
                    .child(
                        div()
                            .h_full()
                            .w(gpui::relative(progress))
                            .rounded_full()
                            .bg(rgb(0xf4f5f7)),
                    ),
            )
            .child(
                div()
                    .flex()
                    .items_center()
                    .justify_between()
                    .child(self.button("play", play_label, cx, |this, _| {
                        this.video.toggle_pause()
                    }))
                    .child(time)
                    .child(self.button("fullscreen", "Fullscreen", cx, |_, window| {
                        window.toggle_fullscreen()
                    })),
            )
            .into_any_element()
    }
}

impl Render for Player {
    fn render(&mut self, _window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        // No background: transparent pixels are where the video shows through.
        let controls = self.controls_visible().then(|| self.controls(cx));
        div()
            .id("stage")
            .size_full()
            .relative()
            .track_focus(&self.focus)
            .on_key_down(cx.listener(Self::on_key))
            .on_mouse_move(cx.listener(|this, _: &MouseMoveEvent, _, cx| this.poke(cx)))
            .on_mouse_down(
                MouseButton::Left,
                cx.listener(|this, _: &MouseDownEvent, _, cx| {
                    this.video.toggle_pause();
                    this.poke(cx);
                }),
            )
            .children(controls)
    }
}

fn main() {
    let source = std::env::args()
        .nth(1)
        .unwrap_or_else(|| TEST_PATTERN.to_owned());

    Application::new().run(move |cx: &mut App| {
        let bounds = Bounds::centered(None, size(px(1280.0), px(720.0)), cx);
        let options = WindowOptions {
            window_bounds: Some(WindowBounds::Windowed(bounds)),
            titlebar: Some(TitlebarOptions {
                title: Some("Video Player".into()),
                ..Default::default()
            }),
            ..Default::default()
        };
        cx.open_window(options, |window, cx| {
            cx.new(|cx| Player::new(&source, window, cx).expect("failed to start the player"))
        })
        .expect("failed to open the window");
        cx.activate(true);
    });
}
